-- The two checklists published on 2026-10-27: The First Week of Looking for
-- Work (Job Search) and Pacing a Week With a Long-Term Condition (Pacing).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-27`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-first-week-of-looking-for-work', 'The First Week of Looking for Work', 'For the first week of looking for work, before the routine exists. It gives the search office hours instead of the whole day, trades thirty applications for three good ones, keeps one sheet of what went where, and expects silence more often than a no.', 'Job Search', '["Give it office hours, not all day — a search that fills the day empties the week.", "Send three good applications, not thirty — the scattergun costs you and lands nothing.", "Keep one sheet of what you sent and when — the follow-up is where half the replies come from.", "Rewrite the top third for each job — the rest of the page can stay as it is.", "Message one person a day you already know — most jobs move through people, not portals.", "Expect silence more often than a no — a feed of nothing is the normal texture of this.", "Put one thing in the week that is not the search — a search with no life around it stalls.", "Say the number you need out loud — knowing your floor makes the questions easier.", "Stop at a set time each day — the laptop closing is what makes tomorrow possible."]'::jsonb, 'weekly', array['Work', 'Resilience']::text[], 1, '2026-10-27T16:00:00+00:00'::timestamptz),
  ('pacing-a-week-with-a-long-term-condition', 'Pacing a Week With a Long-Term Condition', 'For living with a condition whose cost varies, where a good day borrows from tomorrow. It treats energy as a budget, puts the rest in the calendar before the plans, splits the big job across three days, and keeps a short note of what cost what.', 'Pacing', '["Write what you have to spend this week — energy is a budget before it is a feeling.", "Put the rest in the calendar first — rest that is left over never happens.", "Stop each task before you have to — finishing on empty costs tomorrow as well.", "Plan a quiet day either side of the big one — a wedding takes three days, not one.", "Break the one big job into three — the same work over three days costs less.", "Notice the good day for what it is — a good day is not proof the pacing was wrong.", "Keep one short note of what cost what — the pattern is only visible written down.", "Say no with the reason left out — “I can''t this week” is a complete sentence.", "Let the plan change without a verdict — a body that varies is not a failure of will."]'::jsonb, 'weekly', array['Body', 'Self-Compassion']::text[], 1, '2026-10-27T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
